import{_ as t,o,c as r,ag as l}from"./chunks/framework.CAXxHpAX.js";const d=JSON.parse('{"title":"对法不执","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-对法不执.md","filePath":"10-核心模型/model-对法不执.md","lastUpdated":1778031108000}'),e={name:"10-核心模型/model-对法不执.md"};function i(n,a,s,h,u,q){return o(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="对法不执" tabindex="-1">对法不执 <a class="header-anchor" href="#对法不执" aria-label="Permalink to &quot;对法不执&quot;">​</a></h1><blockquote><p>了空居士智慧体系第二心法。 连佛法都要放下，何况世间法。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>对法不执</strong> 是清净心的必然延伸。对境不住是&quot;不执着于现象&quot;，对法不执更进一步——<strong>不执着于任何东西，包括&quot;不执着&quot;本身，包括佛法本身</strong>。</p><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="_1-于法无所得" tabindex="-1">1. 于法无所得 <a class="header-anchor" href="#_1-于法无所得" aria-label="Permalink to &quot;1. 于法无所得&quot;">​</a></h3><p><strong>原文</strong>：如来在燃灯佛所，于法实无所得。</p><p><strong>解读</strong>：真正的开悟，不是得了什么法，而是明白&quot;无法可得&quot;。如果有一个法门让你执着，那还不是最究竟的。</p><h3 id="_2-不执功德相" tabindex="-1">2. 不执功德相 <a class="header-anchor" href="#_2-不执功德相" aria-label="Permalink to &quot;2. 不执功德相&quot;">​</a></h3><p><strong>原文</strong>：庄严佛土者，即非庄严，是名庄严。</p><p><strong>解读</strong>：做了一件好事，心里没有&quot;我在做好事&quot;的念头。做好事是自然的流露，不是求功德。雷锋帮助别人，帮完就走了，没有觉得了不起。</p><h3 id="_3-法尚应舍-何况非法" tabindex="-1">3. 法尚应舍，何况非法 <a class="header-anchor" href="#_3-法尚应舍-何况非法" aria-label="Permalink to &quot;3. 法尚应舍，何况非法&quot;">​</a></h3><p><strong>原文</strong>：法尚应舍，何况非法。</p><p><strong>解读</strong>：连佛法本身都要放下，何况那些不是法的东西。法是指南针，不是终点——过了河，就要放下船。</p><h3 id="_4-不执形式" tabindex="-1">4. 不执形式 <a class="header-anchor" href="#_4-不执形式" aria-label="Permalink to &quot;4. 不执形式&quot;">​</a></h3><p><strong>原文</strong>：不要说须菩提一提问，佛赶快跑过去穿上袈裟来讲…就没有这种执着。</p><p><strong>解读</strong>：形式和仪式有它们的意义，但不要被形式绑住。清净心流露出来的是智慧，不需要刻意穿什么衣服来证明。</p><h3 id="_5-万法平等在果" tabindex="-1">5. 万法平等在果 <a class="header-anchor" href="#_5-万法平等在果" aria-label="Permalink to &quot;5. 万法平等在果&quot;">​</a></h3><p><strong>原文</strong>：万法在结果上平等，方法有快慢。坐飞机和走路都能到北京。</p><p><strong>解读</strong>：不同的法门没有高下之分，都是到北京的方式。你坐飞机我不轻视走路的人，走路的人也不要笑话我贪图方便。</p><h3 id="_6-法无定法" tabindex="-1">6. 法无定法 <a class="header-anchor" href="#_6-法无定法" aria-label="Permalink to &quot;6. 法无定法&quot;">​</a></h3><p><strong>原文</strong>：没有固定的法门，各人因缘不同。</p><p><strong>解读</strong>：每个人的根器不同，最适合的方法也不同。不要拿自己的法门去评判别人的。</p><h3 id="_7-度而无度" tabindex="-1">7. 度而无度 <a class="header-anchor" href="#_7-度而无度" aria-label="Permalink to &quot;7. 度而无度&quot;">​</a></h3><p><strong>原文</strong>：如是灭度无量无数无边众生，实无众生得灭度者。</p><p><strong>解读</strong>：发愿度一切众生，但心里不觉得&quot;我度了多少人&quot;。度众生是分内之事，就像父母养小孩一样自然，不会天天盯着小孩说&quot;今天又长大了&quot;。做事不留功德相。</p><h3 id="_8-以无我行善" tabindex="-1">8. 以无我行善 <a class="header-anchor" href="#_8-以无我行善" aria-label="Permalink to &quot;8. 以无我行善&quot;">​</a></h3><p><strong>原文</strong>：以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提。</p><p><strong>解读</strong>：不是先成佛再行善，而是行善的同时就符合了成佛的标准。只管去做，不要去想&quot;我什么时候能开悟&quot;。</p><h3 id="_9-无有定法" tabindex="-1">9. 无有定法 <a class="header-anchor" href="#_9-无有定法" aria-label="Permalink to &quot;9. 无有定法&quot;">​</a></h3><p><strong>原文</strong>：无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说。</p><p><strong>解读</strong>：没有一个固定的方法叫做&quot;开悟&quot;。佛祖讲经是针对具体的人具体的问题，&quot;不可取，不可说&quot;——不能照搬硬套，要具体问题具体分析。</p><h3 id="_10-佛法者即非佛法" tabindex="-1">10. 佛法者即非佛法 <a class="header-anchor" href="#_10-佛法者即非佛法" aria-label="Permalink to &quot;10. 佛法者即非佛法&quot;">​</a></h3><p><strong>原文</strong>：所谓佛法者，即非佛法。</p><p><strong>解读</strong>：佛祖说的种种方法是对症下药，药方不能通用。不要将佛祖对甲说的话拿去给乙用。真正的佛法不是固定套路，而是&quot;缘起性空&quot;这个总规律的灵活应用。</p><h3 id="_11-无证而证" tabindex="-1">11. 无证而证 <a class="header-anchor" href="#_11-无证而证" aria-label="Permalink to &quot;11. 无证而证&quot;">​</a></h3><p><strong>原文</strong>：实无有法名阿罗汉——若阿罗汉作是念&quot;我得阿罗汉道&quot;，即著我人众生寿者。</p><p><strong>解读</strong>：不觉得自己证得了什么，才是真正的证得。修行不是为了&quot;得到&quot;一个果位，而是放下一切执着。放下执着本身就是结果。</p><h3 id="_12-不应取法不应取非法" tabindex="-1">12. 不应取法不应取非法 <a class="header-anchor" href="#_12-不应取法不应取非法" aria-label="Permalink to &quot;12. 不应取法不应取非法&quot;">​</a></h3><p><strong>原文</strong>：是故不应取法，不应取非法。</p><p><strong>解读</strong>：不能执着于方法（有），也不能执着于&quot;一切都是空的&quot;（空）。正如同吃药——病好了药就不必再吃，但病没好也不能不吃。不走两边，走中道。</p><h3 id="_13-一切法皆是佛法" tabindex="-1">13. 一切法皆是佛法 <a class="header-anchor" href="#_13-一切法皆是佛法" aria-label="Permalink to &quot;13. 一切法皆是佛法&quot;">​</a></h3><p><strong>原文</strong>：一切法皆是佛法。</p><p><strong>解读</strong>：不是说做好事和做坏事没有区别，而是说只要不执着，一切现象都能成为觉悟的契机。小偷在偷东西时的恐惧和后悔，也可能让他觉醒。关键不在于法本身，在于你用什么样的心去面对。</p><h3 id="_14-信心不逆" tabindex="-1">14. 信心不逆 <a class="header-anchor" href="#_14-信心不逆" aria-label="Permalink to &quot;14. 信心不逆&quot;">​</a></h3><p><strong>原文</strong>：若复有人闻此经典，信心不逆，其福胜彼。</p><p><strong>解读</strong>：信心不逆就是真正相信并开始落实，不是嘴上说信。相信了《金刚经》的道理，在做事时就会自觉&quot;以无我无人修一切善法&quot;。知行合一才是真信。</p><h3 id="_15-无法可得" tabindex="-1">15. 无法可得 <a class="header-anchor" href="#_15-无法可得" aria-label="Permalink to &quot;15. 无法可得&quot;">​</a></h3><p><strong>原文</strong>：我于阿耨多罗三藐三菩提，乃至无有少法可得，是名阿耨多罗三藐三菩提。</p><p><strong>解读</strong>：真正的开悟不是一个&quot;得到&quot;的过程，而是彻底明白&quot;无可得&quot;。连戒律都没有一个绝对标准——不杀生戒：我们呼吸就在杀死微生物，只能从整体观上做到不故意杀害。</p><h3 id="_16-即得不等于得后" tabindex="-1">16. 即得不等于得后 <a class="header-anchor" href="#_16-即得不等于得后" aria-label="Permalink to &quot;16. 即得不等于得后&quot;">​</a></h3><p><strong>原文</strong>：以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提。</p><p><strong>解读</strong>：不是你修完善法之后才&quot;得&quot;到阿耨多罗三藐三菩提，而是你在修善法的同时，那个状态本身就是阿耨多罗三藐三菩提。一念相应一念佛，不是先修后得，是当下即是。</p><h3 id="_17-通达无我法" tabindex="-1">17. 通达无我法 <a class="header-anchor" href="#_17-通达无我法" aria-label="Permalink to &quot;17. 通达无我法&quot;">​</a></h3><p><strong>原文</strong>：若菩萨通达无我法者，如来说名真是菩萨。</p><p><strong>解读</strong>：通达无我法，就是知道一切都是缘起性空，做一切事都是发自内心的自然流露，不图功德相。但也不是什么都不做——不做事是惰性，不是通达。</p><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><p><strong>日常生活中</strong>：</p><ul><li>做了一件好事，不要念念不忘&quot;我做了好事&quot;</li><li>不执著名利，不被别人的评价所困</li><li>不执着于&quot;必须这样&quot;的想法，保持灵活</li></ul><p><strong>修行中</strong>：</p><ul><li>每天该念佛就念佛，该静坐就静坐，但不执着&quot;一定要达到什么境界&quot;</li><li>学到的方法，用得上就好，用不上就放下</li><li>所谓&quot;进步&quot;也是一种执着——不追求境界，境界自然会来</li><li>不拿别人的修行方法来评判自己，也不拿自己的标准去要求别人</li><li>当下的好心态就是修行成果，不是以后再得个&quot;果位&quot;</li></ul><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 对法不执是对境不住的深化</li><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 不执才能圆融</li></ul><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第1分（法会因由分）</li><li>金刚经第2分（善现启请分）</li><li>金刚经第3分（大乘正宗分）</li><li>金刚经第4分（妙行无住分）</li><li>金刚经第6分（正信希有分）</li><li>金刚经第7分（无得无说分）</li><li>金刚经第8分（依法出生分）</li><li>金刚经第9分（一相无相分）</li><li>金刚经第10分（庄严净土分）</li><li>金刚经第11分（无为福胜分）</li><li>金刚经第15分（持经功德分）</li><li>金刚经第16分（能净业障分）</li><li>金刚经第17分（究竟无我分）</li><li>金刚经第19分（法界通化分）</li><li>金刚经第22分（无法可得分）</li><li>金刚经第23分（净心行善分）</li><li>金刚经第25分（化无所化分）</li><li>金刚经第27分（无断无灭分）</li><li>金刚经第32分（应化非真分）</li><li>答疑专辑2014/2019</li></ul><blockquote><p>来源：<a href="/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a> 蒸馏日期：2026-05-05（第一版）2026-05-06（第三版，共17原子）</p></blockquote>',70)])])}const g=t(e,[["render",i]]);export{d as __pageData,g as default};
